window.SEG=[{"i": 0, "a": 0.25, "b": 1.898, "text": "اليد اللي انحطت على كتفي…"}, {"i": 1, "a": 2.379, "b": 4.892, "text": "كانت يد شخص صوته نفس صوت أبوي!"}, {"i": 2, "a": 5.305, "b": 8.095, "text": "لكن أبوي كان للحين يكلمني بالجوال ويصرخ:"}, {"i": 3, "a": 8.424, "b": 8.939, "text": "«نواف…"}, {"i": 4, "a": 9.196, "b": 9.949, "text": "لا تلتفت!»"}, {"i": 5, "a": 10.329, "b": 11.349, "text": "تجمدت مكاني."}, {"i": 6, "a": 11.69, "b": 13.733, "text": "كنت أحس بأصابعه تضغط على كتفي…"}, {"i": 7, "a": 14.112, "b": 15.326, "text": "وأسمع أنفاسه."}, {"i": 8, "a": 15.707, "b": 16.464, "text": "لكن فجأة…"}, {"i": 9, "a": 16.824, "b": 17.499, "text": "جتني فكرة."}, {"i": 10, "a": 17.861, "b": 19.623, "text": "فتحت الكاميرا الأمامية،"}, {"i": 11, "a": 19.931, "b": 22.706, "text": "وحاولت أشوف مين اللي واقف خلفي."}, {"i": 12, "a": 23.076, "b": 23.556, "text": "وهنا…"}, {"i": 13, "a": 23.881, "b": 24.707, "text": "كانت الصدمة."}, {"i": 14, "a": 25.081, "b": 25.663, "text": "بالكاميرا…"}, {"i": 15, "a": 26.029, "b": 27.287, "text": "ما كان فيه أحد وراي!"}, {"i": 16, "a": 27.626, "b": 29.973, "text": "لكن كنت للحين أحس باليد على كتفي!"}, {"i": 17, "a": 30.372, "b": 32.1, "text": "سمعت أبوي يقول من الجوال:"}, {"i": 18, "a": 32.426, "b": 32.953, "text": "«نواف…"}, {"i": 19, "a": 33.209, "b": 33.903, "text": "اسمعني…"}, {"i": 20, "a": 34.249, "b": 35.943, "text": "امشِ باتجاه درج الطوارئ…"}, {"i": 21, "a": 36.178, "b": 38.064, "text": "ولا ترد على أي شيء تسمعه!»"}, {"i": 22, "a": 38.51, "b": 39.591, "text": "بديت أمشي…"}, {"i": 23, "a": 39.956, "b": 40.407, "text": "خطوة…"}, {"i": 24, "a": 40.812, "b": 41.436, "text": "خطوتين…"}, {"i": 25, "a": 41.795, "b": 42.313, "text": "وفجأة…"}, {"i": 26, "a": 42.676, "b": 44.346, "text": "الشخص اللي وراي همس:"}, {"i": 27, "a": 44.812, "b": 46.081, "text": "«لا تصدقه يا نواف…"}, {"i": 28, "a": 46.417, "b": 49.196, "text": "هو اللي قفل الباب علينا قبل سبع سنوات!»"}, {"i": 29, "a": 49.606, "b": 51.069, "text": "هنا قلبي وقف."}, {"i": 30, "a": 51.385, "b": 52.503, "text": "قبل سبع سنوات؟!"}, {"i": 31, "a": 52.82, "b": 53.418, "text": "وش يقصد؟"}, {"i": 32, "a": 53.787, "b": 55.672, "text": "أول ما وصلت باب الدرج وفتحته…"}, {"i": 33, "a": 56.013, "b": 57.481, "text": "اختفت اليد من على كتفي!"}, {"i": 34, "a": 57.865, "b": 61.159, "text": "ركضت أطلع الدرج، وما وقفت لين وصلت لشقتنا."}, {"i": 35, "a": 61.467, "b": 62.681, "text": "دقيت الباب بقوة."}, {"i": 36, "a": 62.96, "b": 66.958, "text": "فتح أبوي، وسحبني للداخل، وقفل الباب بكل الأقفال!"}, {"i": 37, "a": 67.209, "b": 69.12, "text": "قلت له: «يبه! وش قاعد يصير؟!"}, {"i": 38, "a": 69.362, "b": 71.174, "text": "وليش صوتك كان موجود بالدور صفر؟!»"}, {"i": 39, "a": 71.542, "b": 72.758, "text": "جلس أبوي على الكرسي،"}, {"i": 40, "a": 73.078, "b": 74.635, "text": "وكان واضح عليه الخوف."}, {"i": 41, "a": 74.968, "b": 75.469, "text": "قلت:"}, {"i": 42, "a": 75.771, "b": 78.113, "text": "«أنت قلت لي إننا أول مرة نسكن هالعمارة!"}, {"i": 43, "a": 78.416, "b": 80.869, "text": "لكن صورتك موجودة فيها من سبع سنوات!»"}, {"i": 44, "a": 81.247, "b": 82.032, "text": "سكت شوي…"}, {"i": 45, "a": 82.351, "b": 83.129, "text": "وبعدين قال:"}, {"i": 46, "a": 83.456, "b": 84.284, "text": "«إيه يا نواف…"}, {"i": 47, "a": 84.652, "b": 85.43, "text": "كذبت عليك."}, {"i": 48, "a": 85.801, "b": 88.87, "text": "قبل سبع سنوات، صار حريق كبير في هالعمارة."}, {"i": 49, "a": 89.237, "b": 89.976, "text": "وذاك اليوم…"}, {"i": 50, "a": 90.342, "b": 91.152, "text": "أنت اختفيت!»"}, {"i": 51, "a": 91.558, "b": 91.983, "text": "قلت:"}, {"i": 52, "a": 92.277, "b": 92.621, "text": "«أنا؟!»"}, {"i": 53, "a": 92.965, "b": 93.382, "text": "قال:"}, {"i": 54, "a": 93.691, "b": 95.753, "text": "«اختفيت أربع ساعات كاملة!"}, {"i": 55, "a": 96.089, "b": 97.568, "text": "دورنا عليك بكل مكان…"}, {"i": 56, "a": 97.866, "b": 98.534, "text": "لين فجأة…"}, {"i": 57, "a": 98.771, "b": 99.93, "text": "رجعت من الدور صفر!"}, {"i": 58, "a": 100.269, "b": 101.105, "text": "لكن المشكلة…"}, {"i": 59, "a": 101.384, "b": 102.804, "text": "إنك ما رجعت لحالك!»"}, {"i": 60, "a": 103.187, "b": 103.714, "text": "سألته:"}, {"i": 61, "a": 104.095, "b": 104.58, "text": "«وش يعني؟!»"}, {"i": 62, "a": 104.971, "b": 105.387, "text": "قال:"}, {"i": 63, "a": 105.707, "b": 107.575, "text": "«كان فيه شخص ثاني رجع معك…"}, {"i": 64, "a": 107.926, "b": 108.801, "text": "نفس وجهك…"}, {"i": 65, "a": 109.083, "b": 109.988, "text": "ونفس صوتك…"}, {"i": 66, "a": 110.343, "b": 111.525, "text": "وحتى ذكرياتك!»"}, {"i": 67, "a": 111.915, "b": 112.946, "text": "قلت له: «أنا مصدوم…"}, {"i": 68, "a": 113.317, "b": 114.79, "text": "يعني كان فيه اثنين مني؟!»"}, {"i": 69, "a": 115.198, "b": 116.257, "text": "هز راسه وقال:"}, {"i": 70, "a": 116.573, "b": 116.952, "text": "«إيه…"}, {"i": 71, "a": 117.302, "b": 117.953, "text": "والمصيبة…"}, {"i": 72, "a": 118.246, "b": 120.635, "text": "إننا ما عرفنا مين فيكم نواف الحقيقي!»"}, {"i": 73, "a": 121.065, "b": 121.591, "text": "وفجأة…"}, {"i": 74, "a": 121.874, "b": 124.004, "text": "سمعنا ثلاث دقات على باب الشقة!"}, {"i": 75, "a": 124.348, "b": 124.716, "text": "طق…"}, {"i": 76, "a": 125.05, "b": 125.422, "text": "طق…"}, {"i": 77, "a": 125.757, "b": 126.113, "text": "طق…"}, {"i": 78, "a": 126.484, "b": 127.031, "text": "وبعدها…"}, {"i": 79, "a": 127.29, "b": 129.135, "text": "سمعنا صوتي أنا من ورا الباب:"}, {"i": 80, "a": 129.448, "b": 131.999, "text": "«يبه… افتح! أنا نواف الحقيقي!"}, {"i": 81, "a": 132.221, "b": 134.099, "text": "اللي عندك داخل البيت… مو ولدك!»"}, {"i": 82, "a": 134.503, "b": 135.278, "text": "طالعت أبوي…"}, {"i": 83, "a": 135.622, "b": 136.717, "text": "وأبوي طالع فيني…"}, {"i": 84, "a": 137.078, "b": 138.659, "text": "وبدأ يتراجع عني ببطء!"}, {"i": 85, "a": 139.141, "b": 140.226, "text": "والحين أبي أسألكم…"}, {"i": 86, "a": 140.585, "b": 141.646, "text": "لو كنتوا مكان أبوي…"}, {"i": 87, "a": 142.033, "b": 144.025, "text": "بتصدقون نواف اللي داخل البيت؟"}, {"i": 88, "a": 144.321, "b": 146.379, "text": "ولا نواف اللي واقف ورا الباب؟!"}];
